import './neon-last-updated.scss';
import { NeonWidget } from '../shared/neon-widget';
import { dynamicText, createElement, updateDynamicText, updateDynamicAttribute } from '../shared/dom-manipulation';
import { translate, addTranslationListener, parse24HourTime } from '@ps-refarch-ux/mfe-utils';
import { formatDate } from '@ps-refarch-ux/mfe-utils';
export class NeonLastUpdated extends NeonWidget {
    constructor() {
        super(...arguments);
        this.widgetTag = 'neon-last-updated';
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'data-text',
            'data-date',
            'data-time',
            'data-time-zone-string'
        ];
    }
    get lastUpdated() {
        return this.lastUpdatedDate;
    }
    set lastUpdated(value) {
        if (value == null) {
            return;
        }
        this.lastUpdatedDate = value;
        updateDynamicText(this);
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'id':
                updateDynamicAttribute(this, 'id');
                updateDynamicText(this);
                break;
            case 'data-date':
            case 'data-time':
                // case 'data-tz':
                this.updateDateFromAttributes();
                break;
            case 'data-time-zone-string':
                updateDynamicText(this);
                break;
            case 'data-text':
                updateDynamicText(this);
                break;
            default:
        }
    }
    getTimeStamp() {
        return formatDate(this.lastUpdatedDate, 'DATE_TIME_PRETTY', true);
    }
    updateDateFromAttributes() {
        let newDateTime = new Date;
        const dateString = this.getAttribute('data-date');
        const timeString = this.getAttribute('data-time');
        // const timeZoneString = this.getAttribute('data-tz');
        const validDateStringRegex = /^(0[1-9]|1[0-2])\/(0[1-9]|1\d|2[0-9]|3[0-1])\/(19|20)\d{2}$/;
        const validTimeStringRegex = /^([01][0-9]|2[0-3]):[0-5][0-9]$/;
        if (dateString != null) {
            if (validDateStringRegex.test(dateString)) {
                const newDate = new Date(dateString);
                if (newDate) {
                    newDateTime = newDate;
                }
            }
            else {
                console.error(dateString + ' is not a valid date. Expected format is MM/DD/YYYY');
            }
        }
        if (timeString != null) {
            if (validTimeStringRegex.test(timeString)) {
                const newTime = parse24HourTime(timeString);
                if (newTime) {
                    newDateTime.setHours(newTime.getHours(), newTime.getMinutes());
                }
            }
            else {
                console.error(timeString + ' is not a valid Time. Expected HH:mm in 24 hour format');
            }
        }
        // if (timeZoneString != null) {
        //   //time zones have not been implemented in mfe-utils
        // }
        this.lastUpdated = newDateTime;
    }
    getLastUpdatedText() {
        return this.getAttribute('data-text') || translate('neon|Last updated');
    }
    render() {
        return createElement('span', {
            text: dynamicText(() => { return this.getLastUpdatedText() + ' ' + this.getTimeStamp() + this.getTimeZoneString(); })
        });
    }
    connectedCallback() {
        super.connectedCallback();
        this.i18nUnsubscribe = addTranslationListener(() => {
            updateDynamicText(this);
        });
    }
    disconnectedCallback() {
        if (this.i18nUnsubscribe != null) {
            this.i18nUnsubscribe();
            this.i18nUnsubscribe = undefined;
        }
    }
    //Gets the time zone string postfix with preceeding space if the time zone string exists.
    //Returns '' otherwise.
    getTimeZoneString() {
        const tzString = this.getAttribute('data-time-zone-string');
        if (tzString != null) {
            return ' ' + tzString;
        }
        else {
            return '';
        }
    }
}
